{
  "title": "Ecosystem controls",
  "description": "Change these while it runs. Restart begins a new world with the current settings.",
  "width": 900,
  "height": 84,
  "controls": [
    { "type": "slider", "label": "Rabbit breeding", "bind": "eco_rabbit_breed", "default": 0.04, "min": 0.01, "max": 0.1, "step": 0.01, "precision": 2, "x": 0, "y": 0, "width": 170, "height": 64 },
    { "type": "slider", "label": "Food per rabbit (fox)", "bind": "eco_fox_food", "default": 16, "min": 8, "max": 40, "step": 2, "x": 182, "y": 0, "width": 170, "height": 64 },
    { "type": "slider", "label": "Grass regrowth", "bind": "eco_grass_regrow", "default": 0.006, "min": 0.002, "max": 0.02, "step": 0.001, "precision": 3, "x": 364, "y": 0, "width": 170, "height": 64 },
    { "type": "slider", "label": "Speed", "bind": "eco_speed", "default": 2, "min": 1, "max": 5, "step": 1, "suffix": "×", "x": 546, "y": 0, "width": 170, "height": 64 },
    { "type": "button", "label": "Restart", "icon": "fa-rotate-left", "bind": "eco_restart", "action": "increment", "x": 740, "y": 14, "width": 160, "height": 42 }
  ]
}
